// Source-derived mission text from Washington Z.C. rulebook, pp. 18–29.
private val washingtonMissionDetails = mapOf(
"M1" to WashingtonMissionInfo("Facing the Impossible", "Medium", "45 minutes", listOf("2V","7R","4R","5R","8R","3R"), "Open all doors in the diner and take all Objective cards.", briefing = "Where were you when the zombie invasion began? We were everyday people minding our businesses in Washington, D.C. The first screams, gunshots, and sirens came quickly. A small war around the White House attracted zombies. We helped people and opened a locked diner, allowing many people to escape.", objectives = listOf("Open all doors in the diner (tiles 3R and 4R).", "Take all Objective cards.", "Starting hour: 12pm."), specialRules = listOf("Setup: place 1 Survivor per Survivor Starting Zone; place 6 permanent Noise tokens in the indicated Zone on tile 4R.", "They are going to the White House!: Zombies choosing the Zone with 6 Noise tokens move toward it as if all doors were open, but closed doors still block them.", "Rescue first!: while a tile has an Objective card, its Zones cannot be Searched and its Pimpweapon Crate cannot be taken.", "The Humvee cannot be Searched while Objective cards remain on tiles 7R and 8R; Humvee Searches draw from the Secret Service deck.", "Each Pimpweapon Crate gives a random Pimpweapon; the Survivor may reorganize inventory for free."), materials = listOf("6 permanent Noise tokens", "6 Pimpweapon Crates", "7 Objective cards", "1 Humvee token")),
"M2" to WashingtonMissionInfo("Leave No One Behind", "Medium", "60 minutes", listOf("2R","1R","8R","6R","7V","4V"), "Save as many people as possible. Take all Objective cards.", briefing = "The army and Secret Service gathered around the White House, unleashing heavy firepower as zombies converged. The Survivors stayed nearby, looking for people to help.", objectives = listOf("Save as many people as possible. Take all Objective cards.", "Starting hour: 12pm."), specialRules = listOf("Zombie exodus: place 6 permanent Noise tokens in the indicated Zone on tiles 1R/2R. Any Zombie starting a Move Step there is placed on the Starting Spawn Zone and ends its Move Step.", "Each Pimpweapon Crate gives a random Pimpweapon; the Survivor may reorganize inventory for free.", "Humvee Searches draw from the Secret Service deck."), materials = listOf("6 permanent Noise tokens", "6 Pimpweapon Crates", "6 Objective cards", "1 Humvee token")),
"M3" to WashingtonMissionInfo("DEFCON 5: Fade Out", "Medium", "45 minutes", listOf("6V","8V","3V","4V","1V","2V"), "Explore the area and take the Objective cards, except the card revealed automatically at 7 PM.", briefing = "As the White House uproar faded into silence, zombies stopped marching toward the presidential building and wandered the streets. The Survivors needed food, a radio, and a way out.", objectives = listOf("Explore the area and take all Objective cards except the card marked to be read at 7 PM; it cannot be taken and is revealed automatically.", "Starting hour: 11am."), specialRules = listOf("One way in: buildings can only be opened from doors with Objective cards. Once a building is opened this way, any of its doors can be opened.", "Each Pimpweapon Crate gives a random Pimpweapon; the Survivor may reorganize inventory for free."), materials = listOf("6 Pimpweapon Crates", "7 Objective cards")),
"M4" to WashingtonMissionInfo("The War Zone", "Medium", "60 minutes", listOf("10V","11V","9R","1R","6R","3R"), "Turn the projector off, then reach the Exit with all Survivors.", briefing = "A light beam was attracting zombies back to the White House. The Survivors found a military convoy and a projector on a Humvee; the soldiers had fought and died in the surrounding buildings. The area was a war zone.", objectives = listOf("Turn the projector off.", "Reach the Exit with all Survivors. A Survivor may escape at the end of their Turn if no Zombies are in the Exit Zone.", "Starting hour: 12am."), specialRules = listOf("Setup: replace the Pimpweapon Crate on tile 10V with the Corpse Pile Objective card.", "The Green Spawn Zone is inactive at the start of the game.", "Each Pimpweapon Crate gives a random Pimpweapon; the Survivor may reorganize inventory for free."), materials = listOf("5 Pimpweapon Crates", "9 Objective cards", "Light Beam token", "Exit Zone token")),
"M5" to WashingtonMissionInfo("DEFCON 4: Double Take", "Medium", "90 minutes", listOf("13V","12R","11R","10R","15R","14R"), "Explore the White House wing to find a suitable shelter.", briefing = "Practically shoved into the White House by zombies, the Survivors explored the wrecked presidential building. Everyday heroes had fought in every room. They needed a reliable shelter and discovered many secrets.", objectives = listOf("Look for a safe place. Explore the White House wing to find a suitable shelter.", "Starting hour: 3pm."), specialRules = listOf("Barricaded doors: Blue and Green doors cannot be opened normally; Red closed doors cannot be opened at all.", "Fear of the dark: the Green Spawn Zone is inactive at the start of the game.", "Each Pimpweapon Crate gives a random Pimpweapon; the Survivor may reorganize inventory for free."), materials = listOf("6 Pimpweapon Crates", "Objective cards as shown on mission map"))
)
val washingtonMissionInfo: Map<String, WashingtonMissionInfo> = washingtonMissionInfoBase + washingtonMissionDetails
